UPDATE companies SET description='Acadiana Plastics Molding operates from New Iberia, Louisiana, where it was founded in 1989 by Kent Byron. The company remains locally owned and operated, with Byron serving as president and chief executive officer. What began as a three-person venture aimed at filling a regional gap—Louisiana food producers previously had to source injection-molded closures from out of state—has grown into a nearly 100-employee operation.

The 22-acre facility houses injection molding presses ranging from 60 to 500 tons, capable of producing parts from 0.05 grams to over 1,000 grams. Annual output exceeds 500 million closures in sizes from 10 mm to 48 mm, including continuous-thread and tamper-evident styles with custom lining options. The product line also covers 19 standard PET bottle styles and the patented STAT® Vial, a unit-dose heat-seal package for the respiratory market, supported by an in-house vial printing process. Engineering and design consulting are offered alongside molding.

Primary markets include the pepper sauce and condiment sector, where the company says it dominates closure sales, as well as respiratory pharmaceutical packaging and craft beverage brands seeking custom containers.

Byron started the business after recognizing that no Southern Louisiana shop specialized in injection-molded plastic closures, forcing local food manufacturers to look elsewhere. The company emphasizes a partnership-oriented service model rather than a purely transactional one, a philosophy it traces back to its founding vision.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Injection molding", "Closure molding (continuous thread, tamper evident)", "PET bottle molding", "Custom container design and engineering", "Vial printing and customization", "Heat seal packaging (STAT\u00ae Vial)", "Design and consulting services", "Mold building and maintenance"], "industries": ["Pepper sauce and condiment", "Respiratory pharmaceutical packaging", "Craft beverage", "Food packaging"], "materials": ["PET"], "equipment": ["60\u2013500 ton injection molding presses", "Vial printing equipment"], "volume": "Over 500 million closures per year", "lead_time": "", "tolerances": "", "built_on": ["Sole producer of the patented STAT\u00ae Vial for respiratory unit-dose packaging", "Over 500 million closures produced annually", "22-acre facility with 60\u2013500 ton injection molding presses", "In-house engineering and design consulting for custom containers", "Patented closure technology for sizes 10\u201348 mm"], "facts_used": ["Founded 1989 by Kent Byron -> /about", "Locally owned and operated, family leadership -> /about", "Started with 3 employees, now nearly 100 -> /about", "22-acre facility -> /about", "Injection molding presses 60-500 tons, part weight 0.05g-1000g+ -> /about", "Produces over 500 million closures per year, sizes 10-48mm -> /", "19 PET bottle styles -> /", "Continuous thread and tamper evident closures with custom lining -> /", "Sole producer of patented STAT\u00ae Vial for respiratory market -> /", "Vial printing process for customization -> /", "Design and consulting services -> /", "Dominates closure sales in pepper sauce and condiment industry -> /about", "Serves craft brew market -> /", "Team members listed (Kent Byron, Kimen Byron, etc.) -> /about"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "APM''s Manufacturing equipment ranges from 60 to 500 tons capable of part production weights between .05 grams to more than 1,000 grams.", "founded_year": "1989", "employee_count": "nearly 100", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='acadiana-plastics-molding' AND approved AND profile IS NULL;
