UPDATE companies SET description='Amana Furniture Shop operates in Amana, Iowa, a community within the historic Amana Colonies.

In addition to its own lines, the showroom carries American-made upholstered and leather furniture from partner brands Bradington-Young and Temple Furniture.

Its product categories span furniture, home goods, and kitchenware, with concrete examples such as the Savanna Gallery Clock and end-grain cutting boards. The company also appeals to visitors of the Amana Colonies tourist area through its physical showroom.

The company states that its differentiation lies in a commitment to quality that has never wavered since 1855, linking each purchase to the craftsmen who build the products. It highlights sustainability and community as core values, positioning its goods as heirloom-quality items that support local artisans.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted wood product manufacturing", "Cutting board manufacturing", "Clock manufacturing", "Charcuterie board manufacturing", "Furniture retail showroom operation", "E-commerce fulfillment"], "industries": ["Furniture", "Home goods", "Kitchenware", "Home decor"], "materials": ["Hardwood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Legacy of craftsmanship, sustainability, and community dating to 1855", "Handcrafted, Iowa-made wood products (cutting boards, clocks, charcuterie boards)", "American-made upholstered and leather furniture from aligned partner brands", "Purchases directly support the craftsmen who make the products", "Showroom located in the historic Amana Colonies"], "facts_used": ["Location: Amana, Iowa -> /", "Founding legacy dates to 1855 -> /", "Products: handcrafted cutting boards, clocks, charcuterie boards -> /", "Partner brands: Bradington-Young, Temple Furniture -> /", "Showroom address: 724 48th Ave, Amana, IA 52203 -> /", "Materials: hardwood referenced -> /", "Company emphasizes craftsmanship, sustainability, community -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Iowa-made, Quality Furniture & Home Goods; Amana-made items, modern home d\u00e9cor, and American made upholstered and leather furniture", "founded_year": "1855", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='amana-furniture-shop' AND approved AND profile IS NULL;
UPDATE companies SET description='Amdek, Inc. was founded in 1991 in Somerville, Alabama, when Robert Tetzlaff purchased RWT Plastics Systems from his father and renamed it Alabama Molding and Decorating. The company began with three Battenfeld injection molding machines and five customers.

The company provides turnkey contract manufacturing, combining plastic injection molding, pad printing, tool design, and final assembly under one roof. Its Alabama and Oregon plants run Cincinnati Milacron presses ranging from 33 to 165 tons, including a Roboshot unit, and a large-format six-color pad printer added in 2024. Amdek handles short-run prototypes through high-volume production, with secondary operations and assembly integration.

Amdek serves medical, automotive, electronics, and industrial markets. A noted customer is Wilson Sporting Goods, for which the company has printed custom logos since 2009. The firm also produces its own Earth Friendly Cutlery line of compostable utensils.

Amdek emphasizes its BBB accreditation, dual-location logistics for faster delivery, and a design-first approach that optimizes parts before tooling. The company traces its roots to Robert Tetzlaff’s early career selling molding and pad-printing equipment, a background that shaped its focus on integrated decorating and molding solutions.', certifications=ARRAY['BBB Accredited Business']::text[], profile='{"capabilities": ["Plastic injection molding", "Pad printing", "Injection mold tool design", "Contract manufacturing", "Short-run production", "High-volume production", "Secondary operations", "Assembly integration", "Product design", "Part design", "Engineering support", "Tooling design", "Final assembly"], "industries": ["Medical", "Automotive", "Electronics", "Industrial"], "materials": [], "equipment": ["Battenfeld molding machines", "Cincinnati Milacron 165-ton molding machine", "Cincinnati Milacron 33-ton molding machine", "Cincinnati Milacron Roboshot 165-ton molding machine", "Large format 6-color pad printer"], "volume": "Short-run to high-volume production", "lead_time": "", "tolerances": "", "built_on": [], "facts_used": ["Founded in 1991 by Robert Tetzlaff -> /about-us", "Family-owned, third-generation leadership (Wolf Tetzlaff) -> /about-us", "Dual facilities in Somerville, AL and Sherwood, OR -> /", "Turnkey contract manufacturing: injection molding, pad printing, tool design, assembly -> /", "Equipment: Cincinnati Milacron presses (33-165 ton), Roboshot, large-format 6-color pad printer -> /about-us", "Industries served: Medical, Automotive, Electronics, Industrial -> /", "Customer example: Wilson Sporting Goods (custom logo printing since 2009) -> /about-us", "BBB Accredited Business -> /about-us", "Short-run to high-volume production capabilities -> db", "Compostable plastic material developed in 2014 -> /about-us", "Acquisitions: Custom Impressions (2014), Shepherd Enterprises (2016) -> /about-us"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Amdek is a fully integrated contract manufacturing company offering turnkey injection molding and pad printing capabilities", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='amdek-inc-pad-printing-injection-molding' AND approved AND profile IS NULL;
